/**
 * Access control: the one place a role becomes a permission (AGENTS.md §4.4).
 *
 * Three platform roles rank above each other (`User < Admin < SuperAdmin`) and
 * each tier inherits everything the one below it holds. Narrow, non-staff
 * capabilities ("settle a Computer Village swap") are not roles — they're
 * `domainRoles` carried alongside the role, and they only ever add permissions.
 *
 * Everything here is pure and dependency-free so the same file can run in a
 * backend, in a browser bundle, and in the Expo app. It must never import a
 * Node built-in, `jose`, or Express: the client apps vendor this file verbatim
 * (see `scripts/check-access-sync.mjs` at the workspace root).
 *
 * Every entry point fails closed. An unknown, missing or wrongly-cased role
 * yields no permissions at all — never a default of `User`.
 */

// ── Roles ───────────────────────────────────────────────────────────────────

export const PLATFORM_ROLES = ["User", "Admin", "SuperAdmin"] as const;
export type PlatformRole = (typeof PLATFORM_ROLES)[number];

export const isPlatformRole = (value: unknown): value is PlatformRole =>
  typeof value === "string" && (PLATFORM_ROLES as readonly string[]).includes(value);

/** Higher ranks inherit every permission of the ranks below. */
export const ROLE_RANK: Readonly<Record<PlatformRole, number>> = Object.freeze({
  User: 1,
  Admin: 2,
  SuperAdmin: 3,
});

/**
 * Narrow capabilities granted on top of a person's role. A domain role is not a
 * staff tier and never ranks: it adds exactly the permissions listed below.
 */
export const DOMAIN_ROLES = ["market:salesperson"] as const;
export type DomainRole = (typeof DOMAIN_ROLES)[number];

export const isDomainRole = (value: unknown): value is DomainRole =>
  typeof value === "string" && (DOMAIN_ROLES as readonly string[]).includes(value);

// ── Permissions ─────────────────────────────────────────────────────────────

/** Every permission a route can require. Adding one is a change to this list. */
export const PERMISSIONS = [
  // auth — identity administration
  "auth.users.read",
  "auth.users.create_user",
  "auth.users.create_admin",
  "auth.users.change_role",
  "auth.users.delete",
  // easybuy
  "easybuy.users.create",
  "easybuy.users.read",
  "easybuy.catalog.write",
  "easybuy.receipts.upload",
  "easybuy.receipts.approve",
  "easybuy.admins.create",
  "easybuy.superadmin.access",
  // store
  "store.orders.create",
  "store.admin.access",
  "store.catalog.write",
  "store.orders.manage",
  // market
  "market.vendors.read_phone",
  "market.swap.settle",
  "market.admin.access",
  // reseller
  "reseller.admin.access",
  "reseller.rates.write",
  "reseller.payouts.resolve",
  "reseller.adjustments.write",
  "reseller.bank_account.write",
] as const;

export type Permission = (typeof PERMISSIONS)[number];

export const isPermission = (value: unknown): value is Permission =>
  typeof value === "string" && (PERMISSIONS as readonly string[]).includes(value);

// ── What each role holds ────────────────────────────────────────────────────

/** What an ordinary signed-in person can do. */
const USER_PERMISSIONS: readonly Permission[] = ["easybuy.receipts.upload", "store.orders.create"];

/** What an Admin adds on top of User. */
const ADMIN_PERMISSIONS: readonly Permission[] = [
  "auth.users.read",
  "auth.users.create_user",
  "easybuy.users.create",
  "easybuy.users.read",
  "easybuy.catalog.write",
  "store.admin.access",
  "store.catalog.write",
  "store.orders.manage",
  "market.vendors.read_phone",
  "market.swap.settle",
  "market.admin.access",
  "reseller.admin.access",
];

/** What only a SuperAdmin adds on top of Admin. */
const SUPER_ADMIN_PERMISSIONS: readonly Permission[] = [
  "auth.users.create_admin",
  "auth.users.change_role",
  "auth.users.delete",
  "easybuy.receipts.approve",
  "easybuy.admins.create",
  "easybuy.superadmin.access",
  "reseller.rates.write",
  "reseller.payouts.resolve",
  "reseller.adjustments.write",
  "reseller.bank_account.write",
];

/**
 * The matrix, built by explicit inheritance so no tier can be read in isolation
 * and drift from the one below it.
 */
export const ROLE_PERMISSIONS: Readonly<Record<PlatformRole, readonly Permission[]>> = Object.freeze({
  User: Object.freeze([...USER_PERMISSIONS]),
  Admin: Object.freeze([...USER_PERMISSIONS, ...ADMIN_PERMISSIONS]),
  SuperAdmin: Object.freeze([...USER_PERMISSIONS, ...ADMIN_PERMISSIONS, ...SUPER_ADMIN_PERMISSIONS]),
});

/** `market:salesperson` is deliberately small: the two things a seller on the floor needs. */
export const DOMAIN_ROLE_PERMISSIONS: Readonly<Record<DomainRole, readonly Permission[]>> = Object.freeze({
  "market:salesperson": Object.freeze(["market.vendors.read_phone", "market.swap.settle"] satisfies Permission[]),
});

// Inheritance is the whole point of the matrix, so prove it at import time
// rather than trusting whoever edits the arrays next.
const assertInherits = (higher: PlatformRole, lower: PlatformRole): void => {
  const granted = ROLE_PERMISSIONS[higher];
  const missing = ROLE_PERMISSIONS[lower].filter((permission) => !granted.includes(permission));
  if (missing.length > 0) {
    throw new Error(`ROLE_PERMISSIONS: ${higher} does not inherit ${lower} (missing ${missing.join(", ")})`);
  }
};
assertInherits("Admin", "User");
assertInherits("SuperAdmin", "Admin");

// ── Evaluation ──────────────────────────────────────────────────────────────

/**
 * Who is asking. Anything may arrive here — a verified `UserCaller`, a decoded
 * JWT payload, or junk from a request — so every field is `unknown` and is
 * validated before it is trusted.
 */
export type AccessActor = { readonly role?: unknown; readonly domainRoles?: unknown } | null | undefined;

const roleOf = (actor: AccessActor): PlatformRole | null => {
  if (!actor || typeof actor !== "object") return null;
  return isPlatformRole(actor.role) ? actor.role : null;
};

/** Valid domain roles only; anything else in the claim is dropped, never granted. */
const domainRolesOf = (actor: AccessActor): DomainRole[] => {
  if (!actor || typeof actor !== "object") return [];
  const raw: unknown = actor.domainRoles;
  return Array.isArray(raw) ? raw.filter(isDomainRole) : [];
};

const rankOf = (role: PlatformRole): number => ROLE_RANK[role] ?? 0;

const holdsAsRole = (role: PlatformRole, permission: Permission): boolean =>
  (ROLE_PERMISSIONS[role] ?? []).includes(permission);

const holdsAsDomain = (domainRole: DomainRole, permission: Permission): boolean =>
  (DOMAIN_ROLE_PERMISSIONS[domainRole] ?? []).includes(permission);

/** True only when `actor` is at least `minRole` in the hierarchy. */
export const hasMinRole = (actor: AccessActor, minRole: PlatformRole): boolean => {
  const role = roleOf(actor);
  if (!role || !isPlatformRole(minRole)) return false;
  return rankOf(role) >= rankOf(minRole);
};

/** Whether `actor` holds `permission` through its role or any of its domain roles. */
export const can = (actor: AccessActor, permission: Permission): boolean => {
  const role = roleOf(actor);
  if (!role) return false;
  if (holdsAsRole(role, permission)) return true;
  return domainRolesOf(actor).some((domainRole) => holdsAsDomain(domainRole, permission));
};

/** True when `actor` holds at least one of `permissions` (empty list → false). */
export const canAny = (actor: AccessActor, permissions: readonly Permission[]): boolean =>
  permissions.some((permission) => can(actor, permission));

/** True only when `actor` holds every one of `permissions` (empty list → false). */
export const canAll = (actor: AccessActor, permissions: readonly Permission[]): boolean =>
  permissions.length > 0 && permissions.every((permission) => can(actor, permission));

/**
 * The full permission list for an actor, for UI and for `''`-style debugging.
 * Returns an empty list — not the `User` default — for an unusable role.
 */
export const resolvePermissions = (actor: AccessActor): Permission[] => {
  const role = roleOf(actor);
  if (!role) return [];
  const granted: Permission[] = [...(ROLE_PERMISSIONS[role] ?? [])];
  const add = (permission: Permission): void => {
    if (!granted.includes(permission)) granted.push(permission);
  };
  // Deliberately an array, not a `Set`: this file is vendored verbatim into client apps whose
  // tsconfig targets predate ES2015 (the store web app is ES2020 and cannot spread a `Set`).
  // A linear scan over ~24 entries costs nothing, and one copy of the file must typecheck in
  // every client. Never "modernise" this back to a Set.
  for (const domainRole of domainRolesOf(actor)) {
    for (const permission of DOMAIN_ROLE_PERMISSIONS[domainRole] ?? []) add(permission);
  }
  return granted;
};
